def range_sums(nums, queries):
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)
    return [prefix[r] - prefix[l] for l, r in queries]

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

print(range_sums([2, -1, 4, 3], [(0, 2), (1, 4)]))
print(two_sum([2, 7, 11, 15], 9))

from collections import Counter

def is_palindrome(text):
    clean = ''.join(ch.lower() for ch in text if ch.isalnum())
    return clean == clean[::-1]

def are_anagrams(a, b):
    return Counter(a.lower()) == Counter(b.lower())

print(is_palindrome('A man, a plan, a canal: Panama'))
print(are_anagrams('listen', 'silent'))
print('hello world'.split())

def sorted_pair(nums, target):
    left, right = 0, len(nums) - 1
    while left < right:
        total = nums[left] + nums[right]
        if total == target:
            return (left, right)
        if total < target:
            left += 1
        else:
            right -= 1
    return None

def unique_sorted_in_place(nums):
    if not nums:
        return 0
    write = 1
    for read in range(1, len(nums)):
        if nums[read] != nums[write - 1]:
            nums[write] = nums[read]
            write += 1
    return write

print(sorted_pair([1, 2, 4, 7, 11], 9))
values = [1, 1, 2, 2, 3]
k = unique_sorted_in_place(values)
print(values[:k])

def max_window_sum(nums, k):
    if not 1 <= k <= len(nums):
        return None
    current = sum(nums[:k])
    best = current
    for right in range(k, len(nums)):
        current += nums[right] - nums[right - k]
        best = max(best, current)
    return best

def longest_unique_substring(text):
    last_seen = {}
    left = 0
    best = 0
    for right, char in enumerate(text):
        if char in last_seen:
            left = max(left, last_seen[char] + 1)
        last_seen[char] = right
        best = max(best, right - left + 1)
    return best

print(max_window_sum([2, 1, 5, 1, 3, 2], 3))
print(longest_unique_substring('abcabcbb'))
